        ["Serviço de uso raro; desativar não muda desempenho de forma mensurável."] = "Rarely used service; disabling it doesn't change performance measurably.",
        ["Tarefas opcionais de coleta de dados."] = "Optional data collection tasks.", ["Configurações oficiais do Gerenciador de Conteúdo do Windows."] = "Official Windows Content Delivery Manager settings.",
