    private static readonly (Regex Regex, Func<Match, string> Build)[] V2Patterns =
    {
        P(@"^Análise de (.+)\. Dados lidos do Windows \(WMI e registro\)\.$", m => $"Analysis of {m.Groups[1].Value}. Data read from Windows (WMI and registry)."),
        P(@"^Smart Optimize: análise concluída \((\d+) recomendados, (\d+) já aplicados\)$", m => $"Smart Optimize: analysis finished ({m.Groups[1].Value} recommended, {m.Groups[2].Value} already applied)"),
        P(@"^Smart Optimize: (\d+) de (\d+) ajustes confirmados pelo Windows$", m => $"Smart Optimize: {m.Groups[1].Value} of {m.Groups[2].Value} tweaks confirmed by Windows"),
        P(@"^Recomendações para (.+)$", m => $"Recommendations for {T(m, 1)}"),
        P(@"^(Recomendado|Já aplicado|Não aplicável|Incompatível|Requer revisão|Falha na leitura): (\d+)$", m => $"{T(m, 1)}: {m.Groups[2].Value}"),
        P(@"^(.+) livres de (.+)$", m => $"{m.Groups[1].Value} free of {m.Groups[2].Value}"),
        P(@"^Plano (Base|Intermediário|Avançado)$", m => $"{T(m, 1)} plan"),
        P(@"^(.+) \(faltam: (.+)\)$", m => $"{T(m, 1)} (missing: {m.Groups[2].Value})"),
        P(@"^(\d+) tarefa\(s\) ativa\(s\)\.$", m => $"{m.Groups[1].Value} task(s) enabled."),
        P(@"^Ativos: (.+)$", m => $"Active: {m.Groups[1].Value}"),
        P(@"^Instalado: (.+?)( e mais (\d+))?$", m => $"Installed: {m.Groups[1].Value}" + (m.Groups[3].Success ? $" and {m.Groups[3].Value} more" : "")),
        P(@"^Não foi possível ler( o estado)?: (.+)$", m => $"Could not read{(m.Groups[1].Success ? " the state" : "")}: {m.Groups[2].Value}"),
        P(@"^Estado continua: (.+) O script pode ter pulado a etapa \(veja o registro da execução\)\.$", m => $"State unchanged: {T(m, 1)} The script may have skipped the step (see the run log)."),
        P(@"^(.+) Reinicie para valer\.$", m => $"{T(m, 1)} Restart for it to take effect."),
        P(@"^(\d+) de (\d+) ajustes confirmados$", m => $"{m.Groups[1].Value} of {m.Groups[2].Value} tweaks confirmed"),
        P(@"^Verificação: (\d+) de (\d+) confirmados$", m => $"Verification: {m.Groups[1].Value} of {m.Groups[2].Value} confirmed"),
        P(@"^(Confirmado|Não confirmado) · (.+?)( — (.+))?$", m => $"{(m.Groups[1].Value == "Confirmado" ? "Confirmed" : "Not confirmed")} · {T(m, 2)}" + (m.Groups[4].Success ? " — " + T(m, 4) : "")),
        P(@"^Cada ajuste foi conferido lendo o estado do Windows depois da execução; a saída do script não basta\.( (\d+) ajuste\(s\) não rodaram porque a execução foi cancelada ou não começou\.)?$",
            m => "Each tweak was checked by reading the Windows state after the run; the script output isn't enough." + (m.Groups[2].Success ? $" {m.Groups[2].Value} tweak(s) didn't run because the run was cancelled or didn't start." : "")),
        P(@"^Aplicar (\d+) ajustes em (\d+) etapa\(s\)\? Um ponto de restauração é criado antes, e cada alteração fica no backup\.$", m => $"Apply {m.Groups[1].Value} tweaks in {m.Groups[2].Value} step(s)? A restore point is created first, and each change is backed up."),

        // Command Center
        P(@"^(\d+) ajustes do catálogo aplicados( · (\d+) confirmados na última execução)?$", m => $"{m.Groups[1].Value} catalog tweaks applied" + (m.Groups[3].Success ? $" · {m.Groups[3].Value} confirmed in the last run" : "")),
        P(@"^(.+) · (.+) · (\d+) recomendados$", m => $"{m.Groups[1].Value} · {T(m, 2)} · {m.Groups[3].Value} recommended"),
        P(@"^(\d+) · (.+)$", m => $"{m.Groups[1].Value} · {T(m, 2)}"),
        P(@"^Pouco espaço livre no disco \((\d+)%\)$", m => $"Low free disk space ({m.Groups[1].Value}%)"),
        P(@"^A licença vence em (\d+) dia\(s\)$", m => $"The license expires in {m.Groups[1].Value} day(s)"),
        P(@"^(.+) °C máx\.$", m => $"{m.Groups[1].Value} °C max"),
        P(@"^(\d+) s com limite$", m => $"{m.Groups[1].Value} s limited"),
        P(@"^Opacidade (\d+)%$", m => $"Opacity {m.Groups[1].Value}%"),

        // Performance Lab
        P(@"^(.+) · (\d+) s · (.+) · fonte: (.+)$", m => $"{m.Groups[1].Value} · {m.Groups[2].Value} s · {T(m, 3)} · source: {T(m, 4)}"),
        P(@"^Gravando (\d+) de (\d+) s( · aguardando quadros do processo| · só sensores \(sem PresentMon ou sem processo\))?$",
            m => $"Recording {m.Groups[1].Value} of {m.Groups[2].Value} s" + (m.Groups[3].Value.Contains("aguardando") ? " · waiting for frames from the process" : m.Groups[3].Success && m.Groups[3].Length > 0 ? " · sensors only (no PresentMon or no process)" : "")),
        P(@"^FPS médio (\d+) · 1% low (\d+)$", m => $"Average FPS {m.Groups[1].Value} · 1% low {m.Groups[2].Value}"),
        P(@"^FPS médio (\d+)$", m => $"Average FPS {m.Groups[1].Value}"),
        P(@"^Importado: (\d+) FPS médio\.$", m => $"Imported: {m.Groups[1].Value} average FPS."),
        P(@"^A captura não pôde ser salva: (.+)$", m => $"The capture couldn't be saved: {m.Groups[1].Value}"),
        P(@"^Excluir o teste ""(.+)""\?$", m => $"Delete the test \"{m.Groups[1].Value}\"?"),
        P(@"^Redução de clock informada pelo driver: (.+)$", m => "Clock reduction reported by the driver: " + string.Join(", ", m.Groups[1].Value.Split(", ").Select(Tr))),
        P(@"^(▲ melhor|▼ pior|=) (.+)$", m => (m.Groups[1].Value.StartsWith("▲") ? "▲ better" : m.Groups[1].Value.StartsWith("▼") ? "▼ worse" : "=") + " " + m.Groups[2].Value),
        P(@"^Processos diferentes \((.+) e (.+)\)\.$", m => $"Different processes ({m.Groups[1].Value} and {m.Groups[2].Value})."),
        P(@"^Driver de vídeo diferente \((.+) e (.+)\)\.$", m => $"Different graphics driver ({m.Groups[1].Value} and {m.Groups[2].Value})."),
        P(@"^Versão do Windows diferente \(build (.+) e (.+)\)\.$", m => $"Different Windows version (build {m.Groups[1].Value} and {m.Groups[2].Value})."),
        P(@"^Resolução ou taxa de atualização diferente \((.+) e (.+)\)\.$", m => $"Different resolution or refresh rate ({m.Groups[1].Value} and {m.Groups[2].Value})."),
        P(@"^Plano de energia diferente \((.+) e (.+)\)\.$", m => $"Different power plan ({T(m, 1)} and {T(m, 2)})."),
        P(@"^Performance Lab: captura iniciada \((.+), (\d+) s\)$", m => $"Performance Lab: capture started ({T(m, 1)}, {m.Groups[2].Value} s)"),
        P(@"^Performance Lab: captura salva \((.+?)(, (\d+) FPS médio)?\)$", m => $"Performance Lab: capture saved ({T(m, 1)}" + (m.Groups[3].Success ? $", {m.Groups[3].Value} average FPS" : "") + ")"),
        P(@"^Escolha o executável do PresentMon \(PresentMon-2\.x-x64\.exe\)\.$", _ => "Choose the PresentMon executable (PresentMon-2.x-x64.exe)."),
        P(@"^Arquivo grande demais para ser o PresentMon\.$", _ => "File too large to be PresentMon."),
        P(@"^Não foi possível iniciar o PresentMon\.$", _ => "Could not start PresentMon."),

        // Optimization Lab
        P(@"^Antes: (\d+)/(\d+)$", m => $"Before: {m.Groups[1].Value}/{m.Groups[2].Value}"),
        P(@"^Depois: (\d+)/(\d+)$", m => $"After: {m.Groups[1].Value}/{m.Groups[2].Value}"),
        P(@"^Experimento: (.+)$", m => $"Experiment: {T(m, 1)}"),
        P(@"^Processo (.+) · (\d+) s por gravação · mínimo de (\d+) gravações em cada fase\. Repita sempre a mesma cena, com as mesmas configurações do jogo\.$",
            m => $"Process {m.Groups[1].Value} · {m.Groups[2].Value} s per recording · at least {m.Groups[3].Value} recordings per phase. Always repeat the same scene, with the same game settings."),
        P(@"^Aplicar ""(.+)""\? Ele fica no backup e pode ser revertido no fim do experimento\.$", m => $"Apply \"{T(m, 1)}\"? It stays in the backup and can be reverted at the end of the experiment."),
        P(@"^Faça pelo menos (\d+) gravações antes e (\d+) depois\.$", m => $"Make at least {m.Groups[1].Value} recordings before and {m.Groups[2].Value} after."),
        P(@"^Variação alta entre gravações \(CV (.+)% antes e (.+)% depois\): repita a mesma cena, com a mesma duração\.$", m => $"High variation between recordings (CV {m.Groups[1].Value}% before and {m.Groups[2].Value}% after): repeat the same scene, with the same duration."),
        P(@"^Temperatura da GPU diferente entre as fases \((.+) °C e (.+) °C\): o aquecimento muda o clock\.$", m => $"Different GPU temperature between phases ({m.Groups[1].Value} °C and {m.Groups[2].Value} °C): heat changes the clock."),
        P(@"^Uso de CPU muito diferente \((.+)% e (.+)%\): pode haver outro programa interferindo\.$", m => $"Very different CPU usage ({m.Groups[1].Value}% and {m.Groups[2].Value}%): another program may be interfering."),
        P(@"^Sem diferença comprovada \(mínimo prático: (\d+)% com p < 0,05\)\. Se o ajuste não tem outro motivo, reverter é o mais simples\.$", m => $"No proven difference (practical minimum: {m.Groups[1].Value}% with p < 0.05). If the tweak has no other reason, reverting is simplest."),
        P(@"^Optimization Lab: ajuste mantido \((.+), (.+)%\)$", m => $"Optimization Lab: tweak kept ({T(m, 1)}, {m.Groups[2].Value}%)"),
        P(@"^Optimization Lab: ajuste revertido \((.+)\)$", m => $"Optimization Lab: tweak reverted ({T(m, 1)})"),

        // Diagnóstico
        P(@"^Abrir (.+)$", m => $"Open {T(m, 1)}"),
        P(@"^Diagnóstico inteligente: (\d+) achado\(s\)$", m => $"Smart diagnostics: {m.Groups[1].Value} finding(s)"),
        P(@"^Não foi possível concluir: (.+)$", m => $"Could not finish: {m.Groups[1].Value}"),
        P(@"^GPU em (\d+)% em média e CPU em (\d+)% durante (\d+) s \((.+), (.+)\)\.$", m => $"GPU at {m.Groups[1].Value}% on average and CPU at {m.Groups[2].Value}% over {m.Groups[3].Value} s ({T(m, 4)}, {T(m, 5)})."),
        P(@"^GPU em só (\d+)% com (\d+) FPS, abaixo dos (\d+) Hz do monitor\.$", m => $"GPU at only {m.Groups[1].Value}% with {m.Groups[2].Value} FPS, below the monitor's {m.Groups[3].Value} Hz."),
        P(@"^CPU total em (\d+)% \(um único núcleo saturado não aparece no total\)\.$", m => $"Total CPU at {m.Groups[1].Value}% (a single saturated core doesn't show in the total)."),
        P(@"^O contador ""% Performance Limit"" do Windows ficou acima de zero em (\d+) de (\d+) s \((\d+)%\)\.$", m => $"Windows' \"% Performance Limit\" counter was above zero for {m.Groups[1].Value} of {m.Groups[2].Value} s ({m.Groups[3].Value}%)."),
        P(@"^O driver NVIDIA informou: (.+?)(\. Temperatura máxima (\d+) °C\.|\.)$", m => "The NVIDIA driver reported: " + string.Join(", ", m.Groups[1].Value.Split(", ").Select(Tr)) + (m.Groups[3].Success ? $". Maximum temperature {m.Groups[3].Value} °C." : ".")),
        P(@"^Uso médio de (\d+)% em (\d+) leituras, com (.+) GB instalados\.$", m => $"Average usage of {m.Groups[1].Value}% over {m.Groups[2].Value} readings, with {m.Groups[3].Value} GB installed."),
        P(@"^Arquivo de paginação em (\d+)% de uso\.$", m => $"Page file at {m.Groups[1].Value}% usage."),
        P(@"^(.+) GB livres de (.+) GB \((\d+)%\)\.$", m => $"{m.Groups[1].Value} GB free of {m.Groups[2].Value} GB ({m.Groups[3].Value}%)."),
        P(@"^Disco com alerta de saúde: (.+)$", m => $"Disk with a health alert: {m.Groups[1].Value}"),
        P(@"^O Windows informa o estado ""(.+)"" para este disco\.$", m => $"Windows reports the state \"{m.Groups[1].Value}\" for this disk."),
        P(@"^(.+) é informado como HDD\.$", m => $"{m.Groups[1].Value} is reported as an HDD."),
        P(@"^(.+): (\d+)% da CPU no momento da análise\.$", m => $"{m.Groups[1].Value}: {m.Groups[2].Value}% of CPU at the time of the analysis."),
        P(@"^(\d+) itens ativos na inicialização\.$", m => $"{m.Groups[1].Value} items enabled at startup."),
        P(@"^(\d+) processos em execução\.$", m => $"{m.Groups[1].Value} processes running."),
        P(@"^O plano ativo é Economia de energia (com o notebook na tomada|num desktop)\.$", m => "The active plan is Power saver " + (m.Groups[1].Value.StartsWith("com") ? "with the laptop plugged in." : "on a desktop.")),
        P(@"^(\d+) dispositivo\(s\) com problema de driver$", m => $"{m.Groups[1].Value} device(s) with a driver problem"),
        P(@"^Com erro no Gerenciador de Dispositivos: (.+)$", m => $"With an error in Device Manager: {m.Groups[1].Value}"),
        P(@"^(.+): driver de (.+)\.$", m => $"{T(m, 1)}: driver from {m.Groups[2].Value}."),
        P(@"^""% Performance Limit"" em (\d+)% no momento da análise\.$", m => $"\"% Performance Limit\" at {m.Groups[1].Value}% at the time of the analysis."),
        P(@"^Ligado há (\d+) dias \(a inicialização rápida mantém o kernel entre desligamentos\)\.$", m => $"On for {m.Groups[1].Value} days (Fast Startup keeps the kernel between shutdowns)."),

        // Perfis
        P(@"^(\d+) ajustes$", m => $"{m.Groups[1].Value} tweaks"),
        P(@"^Nome de processo inválido: (.+)$", m => $"Invalid process name: {m.Groups[1].Value}"),
        P(@"^Excluir o perfil ""(.+)""\? Os ajustes já aplicados continuam no backup\.$", m => $"Delete the profile \"{m.Groups[1].Value}\"? Tweaks already applied stay in the backup."),
        P(@"^Ajustes desconhecidos ignorados: (.+)$", m => $"Unknown tweaks ignored: {m.Groups[1].Value}"),
        P(@"^Processos inválidos ignorados: (.+)$", m => $"Invalid processes ignored: {m.Groups[1].Value}"),
        P(@"^Formato de perfil desconhecido \((.+)\)\.$", m => $"Unknown profile format ({m.Groups[1].Value})."),
        P(@"^O arquivo não é um perfil do Qrztweaks: (.+)$", m => $"The file isn't a Qrztweaks profile: {m.Groups[1].Value}"),
        P(@"^Perfil (.+): Modo Jogo ativado ao abrir o jogo$", m => $"Profile {m.Groups[1].Value}: Game Mode turned on when the game opened"),
        P(@"^Perfil (.+): não foi possível ativar o Modo Jogo: (.+)$", m => $"Profile {m.Groups[1].Value}: could not turn on Game Mode: {m.Groups[2].Value}"),
        P(@"^Jogo fechado: Modo Jogo restaurado \((\d+) item\(ns\)\)$", m => $"Game closed: Game Mode restored ({m.Groups[1].Value} item(s))"),
        P(@"^Não foi possível restaurar o Modo Jogo automaticamente: (.+)$", m => $"Could not restore Game Mode automatically: {m.Groups[1].Value}"),
        P(@"^(.+) \(cópia\)$", m => $"{m.Groups[1].Value} (copy)"),

        // Atualizações
        P(@"^Qrztweaks (.+) instalado\.$", m => $"Qrztweaks {m.Groups[1].Value} installed."),
        P(@"^O app continua na versão (.+)\. Tente atualizar de novo em Configurações → Atualizações ou baixe pelo site\.$", m => $"The app is still on version {m.Groups[1].Value}. Try updating again in Settings → Updates or download it from the website."),
        P(@"^Atualizado de (.+) para (.+)$", m => $"Updated from {m.Groups[1].Value} to {m.Groups[2].Value}"),
        P(@"^A atualização para (.+) não foi concluída \(versão atual (.+)\)$", m => $"The update to {m.Groups[1].Value} didn't finish (current version {m.Groups[2].Value})"),
    };
}
